INSERT INTO `exerciciocasoteste` VALUES (120,20,1,NULL,'O construtor que nÃ£o recebe parÃ¢metros da classe Ponto, nÃ£o foi implementado ou nÃ£o segue a assinatura especificada.\n\nRevise este construtor!',1,'import java.io.ByteArrayInputStream;\r\nimport java.io.ByteArrayOutputStream;\r\nimport java.io.InputStream;\r\nimport java.io.PrintStream;\r\nimport java.util.Arrays;\r\nimport java.util.Collection;\r\nimport java.util.Scanner;\r\nimport org.junit.After;\r\nimport org.junit.Before;\r\nimport org.junit.Test;\r\nimport org.junit.Assert;\r\n\r\n\r\n//ATENÃ‡ÃƒO : NÃƒO MUDAR O NOME DOS TESTES\r\npublic class teste_Feeper {\r\n\r\n    private InputStream stdin = null;\r\n    private PrintStream stdout = null;\r\n    private final ByteArrayOutputStream outContent = new ByteArrayOutputStream();\r\n\r\n    @Before\r\n    public void setUpStreams() {\r\n        stdin = System.in;\r\n        stdout = System.out;\r\n        System.setOut(new PrintStream(outContent));\r\n    }\r\n\r\n    @Test\r\n    public void test() throws Exception {\r\n        Ponto ponto1 = new Ponto();\r\n    }\r\n\r\n    @After\r\n    public void cleanUpStreams() throws Exception {\r\n        System.setIn(stdin);\r\n        System.setOut(stdout);\r\n    }\r\n}\r\n'),(121,20,1,'O construtor que inicializa os atributos da classe Ponto nÃ£o estÃ¡ inicializando o atributo x. \n\nRevise este construtor!','O construtor que inicializa os atributos da classe Ponto, nÃ£o foi implementado ou nÃ£o segue a assinatura especificada.\n\nRevise este construtor!',2,'import java.io.ByteArrayInputStream;\r\nimport java.io.ByteArrayOutputStream;\r\nimport java.io.InputStream;\r\nimport java.io.PrintStream;\r\nimport java.util.Arrays;\r\nimport java.util.Collection;\r\nimport java.util.Scanner;\r\nimport org.junit.After;\r\nimport org.junit.Before;\r\nimport org.junit.Test;\r\nimport org.junit.Assert;\r\n\r\n\r\n//ATENÃ‡ÃƒO : NÃƒO MUDAR O NOME DOS TESTES\r\npublic class teste_Feeper {\r\n\r\n    private InputStream stdi