\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = \"\";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         s = \"\";\r\n         char c=\' \';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = \"\";\r\n         char c=\' \';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n',NULL,'2016-05-17 13:30:48',0),(245,20,33,'Ponto','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/**\r\n * Escreva a descriÃƒÂ§ÃƒÂ£o da classe Ponto aqui.\r\n * \r\n * @author CeciÂ­lia \r\n * @version Maio/2016\r\n */\r\n\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n\r\n    //construtor sem nenhum argumento\r\n    public Ponto(){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;    \r\n    }\r\n    \r\n    //mÃƒÂ©todos de acesso (get)\r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    //mÃƒÂ©todos modificadores(set)\r\n    public void setX(int novoX){\r\n        x = novoX;\r\n    }\r\n    \r\n    public void setY(int novoY){\r\n        y = novoY;\r\n    }\r\n    \r\n}\r\n',NULL,'2016-05-17 18:53:04',0),(246,20,33,'Reta','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Reta aqui.\r\n * \r\n * @author CeciÂ­lia \r\n * @version Maio/2016\r\n */\r\n\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n\r\n    //construtor sem nenhum argumento\r\n    public Reta(){\r\n        ponto1 = 0;\r\n        ponto2 = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public Reta(Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;    \r\n    }\r\n    \r\n    //mÃ©odos de acesso (get)\r\n    public int getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public int getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    //mÃ©todos modificadores(set)\r\n    public void setPonto1(int ponto1){\r\n        ponto1 = novoPonto1;\r\n    }\r\n    \r\n    public void setPonto2(int ponto2){\r\n        ponto2 = novoPonto2;\r\n    }\r\n\r\n}\r\n',NULL,'2016-05-17 19:04:57',0),(247,24,33,'NumerosPares','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares{\r\n    private int n;\r\n    \r\n    //construtor sem nenhum argumento\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    //mÃƒÂ©todos de acesso (get)\r\n    public int getN(){\r\n        return n;\r\n    }\r\n\r\n    //mÃƒÂ©todos modificadores(set)\r\n    public void setN(int novoN){\r\n        n = novoN;\r\n    }\r\n	\r\n	public String geraPares(){		\r\n		int inicio = 2;\r\n		String res = \"\";\r\n		\r\n		while(inicio <= n){\r\n			res += inicio + \", \";			\r\n			inicio += 2;\r\n		}		\r\n		res = res.substring(0, res.length()-2);		\r\n		return res;\r\n	}\r\n	\r\n	public int somaNumeros(){\r\n		int soma = 0;\r\n		\r\n		for(int i=1; i<=n; i++){\r\n			soma += i;\r\n		}\r\n		return soma;\r\n	}   \r\n}\r\n',NULL,'2016-05-17 19:17:44',0),(249,22,9,'SocioAtleta','public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n        this.categoria = \"Mirim\";\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = \"Mirim\";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = \"Infantil\";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = \"Juvenil\";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = \"Adulto\";\r\n        } else {\r\n            this.categoria = \"Master\";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + \", \" + categoria;\r\n    }\r\n\r\n}\r\n','public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = \"Mirim\";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = \"Infantil\";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = \"Juvenil\";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = \"Adulto\";\r\n        } else {\r\n            this.categoria = \"Master\";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + \", \" + categoria;\r\n    }\r\n\r\n}\r\n','2016-05-18 00:13:12',0),(250,22,9,'Socio','public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = \"\";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + \", \" + idade + \", \" + nome;\r\n    }\r\n\r\n}\r\n',NULL,'2016-05-18 00:12:01',0);
