\r\n        while( i <= n){\r\n            soma = soma + 1;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),(581,300,'NumerosPares','/* package qualquer; // NÃ£o coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = \"2, \";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +\", \";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),(582,301,'Ponto','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Ponto aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n    public Ponto(){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    public int getX(){\r\n        return x;\r\n    }\r\n    public int getY(){\r\n        return y;\r\n    }\r\n    public String toString(){\r\n        String res = \"(\"+x+\",\"+y+\")\";\r\n        return res;\r\n    }\r\n}\r\n\r\n\r\n'),(583,301,'Reta','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Reta aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n   public Reta (){\r\n   }\r\n   public Reta(Ponto x, Ponto y){\r\n        ponto1 = x;\r\n        ponto2 = y;\r\n   }\r\n   public void setPonto1(Ponto x){\r\n       ponto1 = x;\r\n   }\r\n   public void setPonto2(Ponto y){\r\n       ponto2 = y;\r\n   }\r\n   public Ponto getPonto1(){\r\n       return ponto1;\r\n   }\r\n   public Ponto getPonto2(){\r\n       return ponto2;\r\n   }\r\n   public double getDistancia(){\r\n    int x = ponto2.getX()-ponto1.getX();\r\n    int y = ponto2.getY()-ponto1.getY();\r\n    double j= 0;\r\n    double i=0;\r\n    j= Math.pow(x,2);\r\n    i = Math.pow(y,2);\r\n    double r = j + i;\r\n    \r\n    r = Math.sqrt(r);\r\n    return r;\r\n   }\r\n   public String toString(){\r\n       String srt = \"\";\r\n       srt = \"\\nPonto1 Ã©: \"+\"(\"+ponto1.getX()+\",\"+ponto1.getY()+\")\";\r\n       srt += \"\\nPonto2 Ã©: \"+\"(\"+ponto2.getX()+\",\"+ponto2.getY()+\")\";\r\n       srt += \"\\nDistancia Ã©: \"+getDistancia();\r\n       return srt;\r\n       \r\n   }\r\n}\r\n   '),(584,301,'TestaReta','\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe TestaReta aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (nÃºmero de versÃ£o ou data)\r\n */\r\npublic class TestaReta{\r\n    public static void main(String args[]){\r\n        Teclado t = new Teclado();\r\n        char k= \' \';\r\n        while(k != \'s\'){\r\n        int x = t.leInt(\"Digite o valor de x do ponto1: \");\r\n        int y = t.leInt(\"Digite o valor de y do ponto1: \");\r\n        int x2 = t.leInt(\"Digite o valor de x do ponto2: \");\r\n        int y2 = t.leInt(\"Digite o valor de x do ponto2: \");\r\n        Ponto p1 = new Ponto(x,y);\r\n        Ponto p2 = new Ponto(x2,y2);\r\n        Reta r1 = new Reta(p1,p2);\r\n        System.out.println(r1.toString());\r\n        k = t.leChar(\"Digite s para interromper o processo: \");\r\n    }\r\n    \r\n}\r\n}\r\n'),(585,301,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite faz