n        quadrado += desenhaLinha(nroLinhas);\r\n        for (int i = 1; i <= (nroLinhas-2); i++){\r\n            quadrado += desenhaLinhaVazada(nroLinhas);\r\n        }\r\n        quadrado += desenhaLinha(nroLinhas);\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n'),(808,396,'Desenho','/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Desenho{\r\n    \r\n    // atributos\r\n    private String simbolo;\r\n    \r\n    // construtor\r\n    public Desenho(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    // get\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    // set\r\n    public void setSimbolo(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    \r\n    public String desenhaTriangulo (int linhas){\r\n        String triangulo = \"\";\r\n        for (int i = 1; i <= linhas; i++){\r\n            triangulo += desenhaLinha(i)+\"\\n\";\r\n        }\r\n        return triangulo;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  uma  linha  de  comprimento  comp  e  a  retorna  como  uma String\r\n    public String desenhaLinha (int comp){\r\n        String linha = \"\";\r\n        for (int i = 1; i <= comp; i++){\r\n            linha += simbolo;\r\n        }\r\n        return linha;\r\n    }\r\n    \r\n    /* Esse mÃ©todo desenha uma linha de  comprimento comp e  a  retorna  como  uma String\r\n     * A  diferenÃ§a  deste mÃ©todo  para  o  mÃ©todo desenhaLinha Ã© que  apenas  o  primeiro  e  Ãºltimo\r\n     * caracteres da linha serÃ£o representados pelo sÃ­mbolo\r\n     */\r\n    public String desenhaLinhaVazada (int comp){\r\n        String linha = simbolo;\r\n        for (int i = 1; i <= (comp-2); i++){\r\n            linha += \" \";\r\n        }\r\n        linha += simbolo;\r\n        return linha;\r\n    }\r\n    \r\n    // Esse mÃ©todo desenha  um  quadrado,  onde  o nÃºmero de linhas do mesmo Ã© passado como parÃ¢metro\r\n    public String desenhaQuadrado (int linhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(linhas)+\"\\n\";\r\n        for (int i = 1; i <= (linhas-2); i++){\r\n            quadrado += desenhaLinha(linhas)+\"\\n\";\r\n        }\r\n        quadrado += desenhaLinha(linhas)+\"\\n\";\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String quadrado = \"\";\r\n        quadrado += desenhaLinha(nroLinhas)+\"\\n\";\r\n        for (int i = 1; i <= (nroLinhas-2); i++){\r\n            quadrado += desenhaLinhaVazada(nroLinhas)+\"\\n\";\r\n        }\r\n        quadrado += desenhaLinha(nroLinhas)+\"\\n\";\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n'),(809,397,'Tabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumeto(){\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + \" x \" + i + \" = \" + (numero*i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   '),(810,397,'TestaTabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class TestaTabuada{\r\n    public static void mais(String args[]){\r\n        Teclado t = new Teclado();\r\n        int i = 0;\r\n        while(i != -1){ \r\n            i = t.leInt(\"Digite um nÃºmero ou -1 para sair\");\r\n            if(i != -1){\r\n            Tabuada a = new Tabuada(i);\r\n            System.out.println(a.calculaTabuada()); \r\n           }\r\n        \r\n        }\r\n    }\r\n}\r\n    '),(811,398,'Tabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumeto(){\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = \"\";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + \" x \" + i + \" = \" + (numero*i)+ \"\\n\";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   '),(812,398,'TestaTabuada','\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class TestaTabuada{\r\n    public static void mais(String args[]){\r\n        Teclado t = new Teclado();\r\n        int i = 0;\r\n        while(i != -1){ \r\n            i = t.leInt(\"Digite um nÃºmero ou -1 para sair\");\r\n            if(i != -1){\r\n            Tabuada a = new Tabuada(i);\r\n            System.out.println(a.calculaTabuada()); \r\n           }\r\n        \r\n        }\r\n    }\r\n}\r\n    '),(813,398,'Teclado',' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(\'\\b\');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println (\"Erro de I/O: \" + e);\r\n         }\r\n         catch (NumberForma